2	//! Application routing and HTTP handlers for EduGate Rustica.
3	//!
4	//! This module wires REST endpoints (`/v1/courses`, `/v1/assessments`, …) to handler
5	//! functions, while embedding cross-cutting concerns that an API-Gateway must
6	//! provide in production:
7	//!
8	//! 1. Caching – `GET` responses are cached in-memory for a short, configurable
9	//!    time‐to‐live to absorb bursts of identical traffic coming from mobile apps.
10	//! 2. Monitoring – each handler is traced with [`tracing`] so that latency,
11	//!    error rates and cache hit ratios can be observed in Prometheus/Grafana.
12	//! 3. Error translation – downstream micro-service errors are converted into a
13	//!    uniform JSON envelope understood by front-end clients.
14	//!
15	//! Adding a new endpoint usually boils down to:
16	//!
17	//! ```rust,ignore
18	//! cfg.service(
19	//!     web::resource("/v1/my_new_resource")
20	//!         .route(web::get().to(my_new_handler))
21	//! );
22	//! ```
23	//!
24	//! The heavy lifting (caching, metrics, downstream calls) is factored into small
25	//! helpers so that handlers stay readable.
26	
27	use std::{
28	    env,
29	    time::{Duration, Instant},
30	};
31	
32	use actix_web::{
33	    http::StatusCode,
34	    web::{self, Data, Json, Query},
35	    Error as ActixError, HttpResponse, Responder,
36	};
37	use dashmap::DashMap;
38	use once_cell::sync::Lazy;
39	use reqwest::{Client, Url};
40	use serde::{Deserialize, Serialize};
41	use thiserror::Error;
42	use tracing::{error, info, instrument, warn};
43	
44	/// How long a GET response stays in the in-memory cache.
45	static DEFAULT_TTL: Duration = Duration::from_secs(60);
46	
47	/// Global in-memory response cache.
48	///
49	/// The gateway is intentionally *stateless* except for this cache,
50	/// which is safe to keep in memory because the data is either public
51	/// (e.g. course catalog) or short-lived.
52	static CACHE: Lazy<DashMap<String, CacheEntry>> = Lazy::new(DashMap::new);
53	
54	/// Thin wrapper around [`Client`] injected via DI (see [`init_routes`]).
55	pub type HttpClient = Client;
56	
57	/// Abstraction of *any* downstream request we can cache.
58	#[derive(Debug)]
59	struct CacheEntry {
60	    inserted_at: Instant,
61	    body:       Vec<u8>,
62	    content_ty: &'static str,
63	}
