167	#[instrument(skip(reqwest, pagination))]
168	async fn get_courses(
169	    reqwest: Data<HttpClient>,
170	    pagination: Query<Pagination>,
171	) -> Result<HttpResponse, ActixError> {
172	    let cache_key = format!("courses?limit={}&offset={}", pagination.limit, pagination.offset);
173	
174	    if let Some(hit) = get_from_cache(&cache_key) {
175	        info!(cache = "hit", key = %cache_key, "returning cached response");
176	        return Ok(HttpResponse::Ok()
177	            .content_type(hit.content_ty)
178	            .body(hit.body));
179	    }
180	
181	    info!(cache = "miss", key = %cache_key, "fetching from downstream");
182	    let backend_url = make_backend_url("/courses", pagination.into_inner())?;
183	    let start = Instant::now();
184	    let res = reqwest.get(backend_url).send().await?;
185	    let status = res.status();
186	    let bytes = res.bytes().await?;
187	
188	    if !status.is_success() {
189	        warn!(status = %status, "downstream returned an error");
190	        return Err(GatewayError::Downstream {
191	            status,
192	            body: String::from_utf8_lossy(&bytes).to_string(),
193	        }
194	        .into());
195	    }
196	
197	    insert_into_cache(&cache_key, &bytes, "application/json");
198	    info!(elapsed_ms = start.elapsed().as_millis(), "courses served");
199	
200	    Ok(HttpResponse::Ok()
201	        .content_type("application/json")
202	        .body(bytes))
203	}
