239	/// Returns a complete downstream URL based on the incoming request.
240	///
241	/// The base URL is configured via the `BACKEND_BASE_URL` environment variable.
242	fn make_backend_url(
243	    path: &str,
244	    pagination: Pagination,
245	) -> Result<Url, GatewayError> {
246	    let base = env::var("BACKEND_BASE_URL").unwrap_or_else(|_| {
247	        "http://localhost:8100".to_string()
248	    });
249	    let mut url = Url::parse(&base)
250	        .map_err(|e| GatewayError::Internal(format!("invalid BACKEND_BASE_URL: {e}")))?;
251	
252	    url.set_path(path);
253	    if path.ends_with("/courses") {
254	        url.query_pairs_mut()
255	            .append_pair("limit", &pagination.limit.to_string())
256	            .append_pair("offset", &pagination.offset.to_string());
257	    }
258	    Ok(url)
259	}
260	
261	/// Inserts the response into the cache together with a TTL.
262	fn insert_into_cache(key: &str, body: &[u8], content_ty: &'static str) {
263	    CACHE.insert(
264	        key.to_string(),
265	        CacheEntry {
266	            inserted_at: Instant::now(),
267	            body: body.to_vec(),
268	            content_ty,
269	        },
270	    );
271	}
272	
273	/// Retrieves an entry from the cache if it exists and is still valid.
274	fn get_from_cache(key: &str) -> Option<CacheEntry> {
275	    match CACHE.get(key) {
276	        Some(entry) if entry.inserted_at.elapsed() <= DEFAULT_TTL => Some(entry.value().clone()),
277	        Some(_) => {
278	            // Expired, purge it.
279	            CACHE.remove(key);
280	            None
281	        }
282	        None => None,
283	    }
284	}
