75	impl Metrics {
76	    fn new() -> Self {
77	        // Registry is intentionally not `lazy_static` so that each `App::data` gets its own copy
78	        // and can be exported independently per gateway instance if required.
79	        let registry = Registry::new();
80	
81	        let req_latency = HistogramVec::new(
82	            HistogramOpts::new("request_latency_seconds", "Gateway request latency"),
83	            &["endpoint"],
84	        )
85	        .expect("valid histogram");
86	        let cache_hits = IntCounterVec::new(
87	            Opts::new("cache_hits_total", "Number of cache hits"),
88	            &["endpoint"],
89	        )
90	        .expect("valid counter");
91	
92	        registry
93	            .register(Box::new(req_latency.clone()))
94	            .expect("histogram registration");
95	        registry
96	            .register(Box::new(cache_hits.clone()))
97	            .expect("counter registration");
98	
99	        Self {
100	            req_latency,
101	            cache_hits,
102	            registry,
103	        }
104	    }
105	}
