125	/// Downstream JSON schemas are opaque to the gateway. We pass them through unchanged.
126	/// However, for stronger typing we at least model the envelope variant returned on errors.
127	#[derive(Serialize)]
128	struct ErrorEnvelope<'a> {
129	    code: u16,
130	    message: &'a str,
