146	impl actix_web::ResponseError for ApiError {
147	    fn status_code(&self) -> StatusCode {
148	        match self {
149	            ApiError::DownstreamUnreachable(_) => StatusCode::BAD_GATEWAY,
150	            ApiError::BadDownstream(code) => *code,
151	            ApiError::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
152	        }
153	    }
