155	    fn error_response(&self) -> HttpResponse {
156	        let body = Json(ErrorEnvelope {
157	            code: self.status_code().as_u16(),
158	            message: self.to_string().as_str(),
159	        });
160	        HttpResponse::build(self.status_code()).json(body.0)
161	    }
162	}
