216	    fn call(&self, req: ServiceRequest) -> Self::Future {
217	        let path_pattern = req.match_pattern().unwrap_or_else(|| req.path().to_owned());
218	        let histogram = self.metrics.req_latency.clone();
219	        let start = Instant::now();
220	
221	        let fut = self.service.call(req);
222	
223	        Box::pin(async move {
224	            let res = fut.await;
225	            histogram
226	                .with_label_values(&[path_pattern.as_str()])
227	                .observe(start.elapsed().as_secs_f64());
228	            res
229	        })
230	    }
