236	#[instrument(skip(state))]
237	#[get("/api/v{version}/courses")]
238	async fn get_courses(
239	    version: web::Path<(u8,)>,
240	    pagination: Query<Pagination>,
241	    state: Data<AppState>,
242	) -> Result<impl Responder, ApiError> {
243	    let (version,) = version.into_inner();
244	    let Pagination { page, per_page } = *pagination;
245	    let endpoint_tag = "courses";
246	
247	    // Build downstream URL
248	    let url = format!(
249	        "{}/v{}/courses?page={}&per_page={}",
250	        state.course_svc_url, version, page, per_page
251	    );
252	    let cache_key = format!("v{version}:{endpoint_tag}:{page}:{per_page}");
253	
254	    // Courses catalogue is requested frequently – cache only first 5 pages.
255	    let should_cache = page <= 5;
256	    if let Some(bytes) = state
257	        .response_cache
258	        .optionally_get_with_if(should_cache, &cache_key)
259	        .await
260	    {
261	        state
262	            .metrics
263	            .cache_hits
264	            .with_label_values(&[endpoint_tag])
265	            .inc();
266	        return Ok(HttpResponse::Ok()
267	            .content_type("application/json")
268	            .body(bytes));
269	    }
270	
271	    // Fetch from downstream service
272	    let res = state
273	        .http_client
274	        .get(&url)
275	        .send()
276	        .await
277	        .context("network failure")?;
278	
279	    let status = res.status();
280	    if !status.is_success() {
281	        return Err(ApiError::BadDownstream(status));
282	    }
283	
284	    let body_bytes = res.bytes().await?;
285	
286	    if should_cache {
287	        // TTL is configured via `RES_CACHE_TTL` env var (default 60s)
288	        state
289	            .response_cache
290	            .insert(
291	                cache_key,
292	                body_bytes.clone(),
293	                Duration::from_secs(CACHE_TTL_SECONDS.get()),
294	            )
295	            .await;
296	    }
297	
298	    Ok(HttpResponse::Ok()
299	        .content_type("application/json")
300	        .body(body_bytes))
301	}
