393	/// Extension trait for `Cache` – provides a convenience `optionally_get_*`.
394	trait CacheExt<K, V> {
395	    fn optionally_get_with_if(
396	        &self,
397	        enabled: bool,
398	        key: &K,
399	    ) -> LocalBoxFuture<'_, Option<V>>
400	    where
401	        K: Clone + Send + Sync + 'static,
402	        V: Clone + Send + Sync + 'static;
403	}
