405	impl<K, V> CacheExt<K, V> for Cache<K, V>
406	where
407	    K: std::hash::Hash + Eq + Send + Sync + Clone + 'static,
408	    V: Clone + Send + Sync + 'static,
409	{
410	    fn optionally_get_with_if(
411	        &self,
412	        enabled: bool,
413	        key: &K,
414	    ) -> LocalBoxFuture<'_, Option<V>> {
415	        if enabled {
416	            Box::pin(self.get(key))
417	        } else {
418	            Box::pin(future::ready(None))
419	        }
420	    }
421	}
