42	/// Alias representing opaque cache keys that identify a unique gateway
43	/// response.  Call `CacheKey::new()` with any hashable payload.
44	#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
45	pub struct CacheKey(u64);
46	
47	impl CacheKey {
48	    /// Build a stable, 64-bit hash from a tuple of arguments.
49	    ///
50	    /// ```
51	    /// let key = CacheKey::new(&("GET", "/v1/public/courses?page=1"));
52	    /// ```
53	    pub fn new<T: Hash + ?Sized>(value: &T) -> Self {
54	        let mut hasher = DefaultHasher::new();
55	        value.hash(&mut hasher);
56	        CacheKey(hasher.finish())
57	    }
58	}
