104	/// Abstraction over any async cache store.
105	#[async_trait]
106	pub trait CacheBackend: Send + Sync + 'static {
107	    /// Obtain a response from the cache.  Returns `Ok(None)` when
108	    /// the entry is missing or expired.
109	    async fn get(&self, key: &CacheKey) -> CacheResult<Option<Arc<CachedResponse>>>;
110	
111	    /// Insert a response with a TTL.
112	    async fn set(
113	        &self,
114	        key: CacheKey,
115	        val: CachedResponse,
116	        ttl: Duration,
117	    ) -> CacheResult<()>;
