126	/* ---------------------------------------------------------------- *\
127	 * In-Memory LRU cache
128	\* ---------------------------------------------------------------- */
129	
130	/// Initial capacity of the LRU map (powers of two are performant).
131	const DEFAULT_LRU_CAPACITY: usize = 1 << 12;
132	
133	/// Single entry stored inside the in-memory cache.
134	#[derive(Debug)]
135	struct Entry {
136	    expires_at: Instant,
137	    response: Arc<CachedResponse>,
138	}
139	
140	#[cfg(feature = "in_memory_cache")]
141	#[derive(Debug)]
142	pub struct InMemoryCache {
143	    /// Tokio broadcast channel for metrics (Hit/Miss/Expired).
144	    events: CacheEventTx,
145	    /// Wrapped LRU cache protected by an `RwLock`.
146	    inner: RwLock<LruCache<CacheKey, Entry>>,
147	}
148	
149	#[cfg(feature = "in_memory_cache")]
150	impl Default for InMemoryCache {
151	    fn default() -> Self {
152	        let (tx, _rx) = broadcast::channel(128);
153	        Self {
154	            events: tx,
155	            inner: RwLock::new(LruCache::new(DEFAULT_LRU_CAPACITY)),
156	        }
157	    }
158	}
159	
160	#[cfg(feature = "in_memory_cache")]
161	#[async_trait]
162	impl CacheBackend for InMemoryCache {
163	    async fn get(&self, key: &CacheKey) -> CacheResult<Option<Arc<CachedResponse>>> {
164	        let mut cache = self.inner.write();
165	        // `get` on `LruCache` promotes the key to MRU.
166	        if let Some(entry) = cache.get(key) {
167	            if entry.expires_at > Instant::now() {
168	                let _ = self.events.send(CacheStatus::Hit);
169	                return Ok(Some(Arc::clone(&entry.response)));
170	            }
171	            // Entry expired – remove it early to free space.
172	            cache.pop(key);
173	            let _ = self.events.send(CacheStatus::Expired);
174	            return Ok(None);
175	        }
176	        let _ = self.events.send(CacheStatus::Miss);
177	        Ok(None)
178	    }
179	
180	    async fn set(
181	        &self,
182	        key: CacheKey,
183	        val: CachedResponse,
184	        ttl: Duration,
185	    ) -> CacheResult<()> {
186	        let mut cache = self.inner.write();
187	        cache.put(
188	            key,
189	            Entry {
190	                expires_at: Instant::now() + ttl,
191	                response: Arc::new(val),
192	            },
193	        );
194	        Ok(())
195	    }
196	
197	    async fn invalidate(&self, key: &CacheKey) -> CacheResult<()> {
198	        let mut cache = self.inner.write();
199	        cache.pop(key);
200	        Ok(())
201	    }
202	
203	    fn metrics_tx(&self) -> &CacheEventTx {
204	        &self.events
205	    }
206	}
