208	/* ---------------------------------------------------------------- *\
209	 * Optional Redis Cache
210	 *
211	 * Enabled when compiled with `--features=redis_cache`.  Delegates
212	 * storage to an external Redis cluster using the RESP protocol.
213	\* ---------------------------------------------------------------- */
214	
215	#[cfg(feature = "redis_cache")]
216	mod redis_backend {
217	    use super::*;
218	    use redis::{aio::ConnectionManager, AsyncCommands};
219	
220	    /// Prefix to prevent key collisions with other applications.
221	    const KEY_PREFIX: &str = "edugate:v1:";
222	
223	    pub struct RedisCache {
224	        events: CacheEventTx,
225	        conn: ConnectionManager,
226	    }
227	
228	    impl RedisCache {
229	        pub async fn new(url: &str) -> CacheResult<Self> {
230	            let (tx, _rx) = broadcast::channel(128);
231	            let client = redis::Client::open(url).map_err(|e| CacheError::Internal(e.to_string()))?;
232	            let mgr = client
233	                .get_tokio_connection_manager()
234	                .await
235	                .map_err(|e| CacheError::Internal(e.to_string()))?;
236	
237	            Ok(Self { events: tx, conn: mgr })
238	        }
239	    }
240	
241	    #[async_trait]
242	    impl CacheBackend for RedisCache {
243	        async fn get(&self, key: &CacheKey) -> CacheResult<Option<Arc<CachedResponse>>> {
244	            let composite = format!("{KEY_PREFIX}{:x}", key.0);
245	            let payload: Option<Vec<u8>> = self
246	                .conn
247	                .get(composite)
248	                .await
249	                .map_err(|_| CacheError::BackendUnavailable)?;
250	            if let Some(raw) = payload {
251	                let resp: CachedResponse = serde_json::from_slice(&raw)?;
252	                let _ = self.events.send(CacheStatus::Hit);
253	                return Ok(Some(Arc::new(resp)));
254	            }
255	            let _ = self.events.send(CacheStatus::Miss);
256	            Ok(None)
257	        }
258	
259	        async fn set(
260	            &self,
261	            key: CacheKey,
262	            val: CachedResponse,
263	            ttl: Duration,
264	        ) -> CacheResult<()> {
265	            let composite = format!("{KEY_PREFIX}{:x}", key.0);
266	            let raw = serde_json::to_vec(&val)?;
267	            // Use SETEX for atomic write + expire
268	            self.conn
269	                .set_ex::<_, _, ()>(composite, raw, ttl.as_secs() as usize)
270	                .await
271	                .map_err(|_| CacheError::BackendUnavailable)?;
272	            Ok(())
273	        }
274	
275	        async fn invalidate(&self, key: &CacheKey) -> CacheResult<()> {
276	            let composite = format!("{KEY_PREFIX}{:x}", key.0);
277	            self.conn
278	                .del::<_, ()>(composite)
279	                .await
280	                .map_err(|_| CacheError::BackendUnavailable)?;
281	            Ok(())
282	        }
283	
284	        fn metrics_tx(&self) -> &CacheEventTx {
285	            &self.events
286	        }
287	    }
288	}
