294	/// Metrics counters shared between all cache backends.
295	#[derive(Debug, Default)]
296	pub struct CacheMetrics {
297	    pub hits: tokio::sync::Mutex<u64>,
298	    pub misses: tokio::sync::Mutex<u64>,
299	    pub expirations: tokio::sync::Mutex<u64>,
300	}
301	
302	static GLOBAL_METRICS: Lazy<CacheMetrics> = Lazy::new(CacheMetrics::default);
303	
304	/// Attach a listener to the supplied backend and increment the
305	/// global counters on every cache event.  Should be called once
306	/// during bootstrap.
307	pub fn wire_metrics<B: CacheBackend>(backend: &B) {
308	    let mut rx = backend.metrics_tx().subscribe();
309	    tokio::spawn(async move {
310	        while let Ok(evt) = rx.recv().await {
311	            match evt {
312	                CacheStatus::Hit => {
313	                    let mut hits = GLOBAL_METRICS.hits.lock().await;
314	                    *hits += 1;
315	                }
316	                CacheStatus::Miss => {
317	                    let mut misses = GLOBAL_METRICS.misses.lock().await;
318	                    *misses += 1;
319	                }
320	                CacheStatus::Expired => {
321	                    let mut ex = GLOBAL_METRICS.expirations.lock().await;
322	                    *ex += 1;
323	                }
324	            }
325	        }
326	    });
327	}
