276	    /* ------------------------------------------------------------ *
277	     * Internals                                                    *
278	     * ------------------------------------------------------------ */
279	
280	    /// Core helper that performs:
281	    ///  1. Cache lookup / insertion
282	    ///  2. Timed HTTP request
283	    ///  3. Metrics emission
284	    ///  4. Error mapping
285	    #[instrument(
286	        skip(self, query),
287	        fields(service = %service.label(), path = path)
288	    )]
289	    async fn fetch_json(
290	        &self,
291	        service: Downstream,
292	        path: &str,
293	        query: Option<&[(&str, String)]>,
294	        ttl: Option<Duration>,
295	    ) -> Result<Value, GatewayError> {
296	        let endpoint = self
297	            .endpoints
298	            .get(&service)
299	            .ok_or(GatewayError::Misconfigured)?;
300	
301	        let mut url = endpoint.url(path)?;
302	        if let Some(q) = query {
303	            let mut pairs = url.query_pairs_mut();
304	            for (k, v) in q {
305	                pairs.append_pair(k, v);
306	            }
307	            drop(pairs);
308	        }
309	
310	        let cache_key = url.as_str().to_owned();
311	        if let Some(value) = self.maybe_get_cached(&cache_key) {
312	            metrics::increment_counter!("cache.hit", "service" => service.label());
313	            debug!("Cache hit for {}", cache_key);
314	            return Ok(value);
315	        }
316	        metrics::increment_counter!("cache.miss", "service" => service.label());
317	        debug!("Cache miss for {}", cache_key);
318	
319	        let start = Instant::now();
320	        let resp = match timeout(self.cfg.request_timeout, self.client.get(url.clone()).send()).await
321	        {
322	            Ok(r) => r?,
323	            Err(_) => return Err(GatewayError::Timeout),
324	        };
325	        let elapsed = start.elapsed();
326	        metrics::histogram!(
327	            "downstream.latency",
328	            elapsed.as_secs_f64(),
329	            "service" => service.label(),
330	            "status" => resp.status().as_str()
331	        );
332	
333	        if !resp.status().is_success() {
334	            let body = resp.text().await.unwrap_or_default();
335	            error!(status = %resp.status(), body = %body, "Downstream error");
336	            return Err(GatewayError::Status {
337	                status: resp.status(),
338	                body,
339	            });
340	        }
341	
342	        let json: Value = resp.json().await?;
343	        if let Some(ttl) = ttl.or(Some(self.cfg.default_ttl)) {
344	            self.insert_cache(cache_key, json.clone(), ttl);
345	        }
346	
347	        Ok(json)
348	    }
349	
350	    /* -------------------- Cache helpers -------------------- */
351	
352	    /// Attempt to pull a value from the cache.
353	    fn maybe_get_cached(&self, key: &str) -> Option<Value> {
354	        let mut cache = self.cache.lock();
355	        if let Some(entry) = cache.get(key) {
356	            if Instant::now() < entry.expires_at {
357	                return Some(entry.value.clone());
358	            }
359	        }
360	        // Either not present or expired — remove so it does not occupy space.
361	        cache.pop(key);
362	        None
363	    }
364	
365	    /// Insert a new value into the cache.
366	    fn insert_cache(&self, key: String, value: Value, ttl: Duration) {
367	        let mut cache = self.cache.lock();
368	        cache.put(
369	            key,
370	            CacheEntry {
371	                expires_at: Instant::now() + ttl,
372	                value,
373	            },
374	        );
375	    }
376	}
