27	/// Semantic API version recognised by the gateway.
28	///
29	/// The `ApiVersion` is parsed from the `Accept-Version` HTTP header
30	/// (`v=<semver>` style) or extracted from the URL path (`/v{major}`).
31	#[derive(Debug, Clone, Copy, Eq, PartialEq, Hash, Serialize, Deserialize)]
32	#[serde(rename_all = "lowercase")]
33	pub enum ApiVersion {
34	    V1,
35	    V2,
36	}
37	
38	impl fmt::Display for ApiVersion {
39	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
40	        let version_str = match self {
41	            ApiVersion::V1 => "v1",
42	            ApiVersion::V2 => "v2",
43	        };
44	        f.write_str(version_str)
45	    }
46	}
