48	/// Pagination helper understood by every collection-returning endpoint.
49	///
50	/// The default `limit` is intentionally low (20) to avoid abuse.
51	#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
52	pub struct Pagination {
53	    #[serde(default = "Pagination::default_limit")]
54	    pub limit: u32,
55	    #[serde(default)]
56	    pub offset: u32,
57	}
58	
59	impl Pagination {
60	    const fn default_limit() -> u32 {
61	        20
62	    }
63	}
