65	/// HTTP cache policy specified by an upstream service.
66	///
67	/// The gateway honours the strongest directive (i.e. *NoCache* over any
68	/// *Public*/**Private* variants) when aggregating multiple sub-requests.
69	#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
70	#[serde(tag = "type", content = "ttl_secs", rename_all = "snake_case")]
71	pub enum CachePolicy {
72	    /// Response must never be cached (e.g. tokens, sensitive PII).
73	    NoCache,
74	    /// Cacheable for *public* clients (shared caches, CDN, etc.).
75	    Public(u32),
76	    /// Cacheable but *only* for the individual authenticated user.
77	    Private(u32),
78	}
79	
80	impl CachePolicy {
81	    /// Convert the `CachePolicy` into a concrete `Duration`, if cacheable.
82	    pub fn ttl(&self) -> Option<Duration> {
83	        match self {
84	            CachePolicy::NoCache => None,
85	            CachePolicy::Public(ttl) | CachePolicy::Private(ttl) => {
86	                Some(Duration::from_secs(u64::from(*ttl)))
87	            }
88	        }
89	    }
90	}
