100	/// A syntactically stable cache key.
101	///
102	/// Keys are generated from the HTTP method, canonicalised path, stable
103	/// query-string order, and the `ApiVersion`.  User-scoped keys append the
104	/// caller's `user_id` to guarantee segregation.
105	#[derive(Debug, Clone, Eq, PartialEq, Hash, Serialize, Deserialize)]
106	pub struct CacheKey(Cow<'static, str>);
