108	impl CacheKey {
109	    /// Build a *public* cache key.
110	    pub fn public(method: &str, canonical_path: &str, version: ApiVersion) -> Self {
111	        let raw = format!("{method}:{version}:{canonical_path}");
112	        Self(Cow::Owned(raw))
113	    }
114	
115	    /// Build a *private* (user-scoped) cache key.
116	    pub fn private(
117	        method: &str,
118	        canonical_path: &str,
119	        version: ApiVersion,
120	        user_id: Uuid,
121	    ) -> Self {
122	        let raw = format!("{method}:{version}:{canonical_path}:user:{user_id}");
123	        Self(Cow::Owned(raw))
124	    }
