152	pub struct Probe {
153	    /// RFC 3339 representation of when the request started processing.
154	    pub started_at: DateTime<Utc>,
155	    /// Nanoseconds elapsed until a response left the gateway.
156	    pub duration_ns: u128,
157	    /// Whether the response came from cache.
158	    pub cache_hit: bool,
159	}
