163	/// Mapping rules:
164	///  • 400-series → client mistake (4xx)
165	///  • 500-series → gateway/upstream failure (5xx)
166	#[derive(Debug, Clone, Copy, Eq, PartialEq, Hash, Serialize, Deserialize)]
167	#[serde(rename_all = "snake_case")]
168	pub enum ErrorKind {
169	    BadRequest,
170	    Unauthorized,
171	    Forbidden,
172	    NotFound,
173	    Conflict,
174	    Timeout,
175	    UpstreamFailure,
176	    Internal,
177	    ServiceUnavailable,
