200	/// Gateway-internal error type with rich context.
201	#[derive(Debug, Clone, Serialize)]
202	pub struct GatewayError<'a> {
203	    pub kind: ErrorKind,
204	    pub message: Cow<'a, str>,
205	    pub request_id: Uuid,
206	    /// Optional opaque source for server logs (excluded from JSON by default).
207	    #[serde(skip_serializing)]
