211	impl<'a> GatewayError<'a> {
212	    /// Create a new user-facing error with no underlying source.
213	    pub fn new(kind: ErrorKind, message: impl Into<Cow<'a, str>>, request_id: Uuid) -> Self {
214	        Self {
215	            kind,
216	            message: message.into(),
217	            request_id,
218	            source: None,
