233	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
234	        write!(
235	            f,
236	            "[{}] {} (request_id = {})",
237	            self.kind as u8, // numeric variant index, stable over builds
238	            self.message,
239	            self.request_id
