263	/// Simple stopwatch used to measure latency per request.
264	///
265	/// Dropping the guard automatically assigns `duration_ns` inside [`Probe`].
266	pub struct Stopwatch {
267	    started: SystemTime,
268	}
269	
270	impl Stopwatch {
271	    #[must_use]
272	    pub fn start() -> Self {
273	        Self {
274	            started: SystemTime::now(),
275	        }
276	    }
277	
278	    /// Finish the measurement and produce a `Probe`.
279	    pub fn finish(self, cache_hit: bool) -> Probe {
280	        let duration_ns = self
281	            .started
282	            .elapsed()
283	            .map(|d| d.as_nanos())
284	            .unwrap_or_default();
